def merge_tool_results(calls, results):
    # Check for duplicate call ids
    seen_ids = set()
    for call in calls:
        id_val = call['id']
        if id_val in seen_ids:
            raise ValueError("Duplicate call id")
        seen_ids.add(id_val)

    # Process results: last result for an id wins, missing content defaults to ''
    processed_results = {}
    for result in results:
        id_val = result['id']
        content = result.get('content', '')
        processed_results[id_val] = content

    # Build result list in call order
    output = []
    for call in calls:
        id_val = call['id']
        if id_val in processed_results:
            output.append({'id': id_val, 'status': 'done', 'content': processed_results[id_val]})
        else:
            output.append({'id': id_val, 'status': 'pending'})

    return output

